from .money import MAX_CENTS, _to_cents, _from_cents, format_amount


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    items = list(amounts)  # snapshot; never mutate the caller's list
    total = 0
    for item in items:
        total += _to_cents(item)
        if total > MAX_CENTS:
            raise ValueError("total exceeds maximum")
    return {"total": format_amount(_from_cents(total)), "count": len(items)}

