import re
from decimal import Decimal

MAX_CENTS = 100000000  # 1000000.00

_STRING_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def _from_parts(negative, digits, exp):
    """Return integer cents for digits * 10**exp, validating the range.

    Uses only integer/string arithmetic so the active decimal context
    (precision, traps, ...) has no influence on the result.
    """
    stripped = digits.lstrip("0")
    if not stripped:
        raise ValueError("amount must be greater than zero")
    if negative:
        raise ValueError("amount must not be negative")
    body = stripped.rstrip("0")
    exp += len(stripped) - len(body)
    if not body:  # pragma: no cover - defensive
        raise ValueError("amount must be greater than zero")
    if exp < -2:
        raise ValueError("amount is not exactly representable in cents")
    # Order of magnitude check before building any potentially huge integer.
    if len(body) + exp + 2 > 12:
        raise ValueError("amount exceeds maximum")
    cents = int(body) * 10 ** (exp + 2)
    if cents > MAX_CENTS:
        raise ValueError("amount exceeds maximum")
    return cents


def _to_cents(value):
    """Validate ``value`` and return its amount as an exact integer of cents."""
    if isinstance(value, bool):
        raise ValueError("invalid amount type")
    if isinstance(value, Decimal):
        if not value.is_finite():
            raise ValueError("amount must be finite")
        sign, digits, exp = value.as_tuple()
        return _from_parts(bool(sign), "".join(map(str, digits)), exp)
    if isinstance(value, int):
        if value <= 0:
            raise ValueError("amount must be greater than zero")
        if value > MAX_CENTS // 100:
            raise ValueError("amount exceeds maximum")
        return value * 100
    if isinstance(value, str):
        match = _STRING_RE.fullmatch(value)
        if match is None or not value.isascii():
            raise ValueError("invalid amount string")
        sign, whole, frac = match.groups()
        frac = frac or ""
        return _from_parts(sign == "-", whole + frac, -len(frac))
    raise ValueError("invalid amount type")


def _from_cents(cents):
    # Tuple construction is exact and independent of the decimal context.
    return Decimal((0, tuple(int(d) for d in str(cents)), -2))


def parse_amount(value):
    return _from_cents(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
